import{_ as t,o as s,c as a,a3 as o}from"./chunks/framework.B02wg2PO.js";const g=JSON.parse('{"title":"Agent Definition Reference","description":"","frontmatter":{},"headers":[],"relativePath":"reference/agent-definition.md","filePath":"reference/agent-definition.md"}'),i={name:"reference/agent-definition.md"};function d(n,e,r,c,l,h){return s(),a("div",null,[...e[0]||(e[0]=[o(`<h1 id="agent-definition-reference" tabindex="-1">Agent Definition Reference <a class="header-anchor" href="#agent-definition-reference" aria-label="Permalink to &quot;Agent Definition Reference&quot;">​</a></h1><p>A custom agent is a directory. Its persona, its permissions, its skills, and the MCP servers it may reach are all files on disk under the agents root — nothing about an agent lives only in a database row. This page is the file format. The end-to-end walkthrough is in <a href="/docs/guides/writing-a-custom-agent">Writing a Custom Agent</a>.</p><h2 id="the-agents-root" tabindex="-1">The agents root <a class="header-anchor" href="#the-agents-root" aria-label="Permalink to &quot;The agents root&quot;">​</a></h2><p>The root is resolved per call, so it follows the tenant scope: <code>SAIDI_AGENTS_DIR</code> when set (tests), otherwise the current workspace&#39;s agents directory.</p><p>A directory becomes an agent when it contains an <code>AGENT.md</code>. A directory without one is skipped entirely — it is not listed, not spawnable, and not editable.</p><p>Directory names are validated as slugs before creation:</p><table tabindex="0"><thead><tr><th>Rule</th><th>Value</th></tr></thead><tbody><tr><td>Length</td><td>2–40 characters</td></tr><tr><td>Shape</td><td><code>^[a-z0-9][a-z0-9-]*$</code> — lowercase letters, digits, dashes</td></tr><tr><td>Reserved</td><td><code>prime</code>, <code>operator</code>, <code>saidi</code>, plus any registered project name</td></tr></tbody></table><h2 id="on-disk-layout" tabindex="-1">On-disk layout <a class="header-anchor" href="#on-disk-layout" aria-label="Permalink to &quot;On-disk layout&quot;">​</a></h2><p>Every file an agent can have:</p><table tabindex="0"><thead><tr><th>Path</th><th>Written by</th><th>What it is</th></tr></thead><tbody><tr><td><code>AGENT.md</code></td><td>you / <code>create_agent</code></td><td>Frontmatter config + the persona prompt. Required</td></tr><tr><td><code>.claude-plugin/plugin.json</code></td><td>scaffold</td><td>Plugin manifest — <code>{ name, description, version }</code></td></tr><tr><td><code>.codex-plugin/plugin.json</code></td><td>you</td><td>Same manifest plus <code>&quot;skills&quot;: &quot;./skills/&quot;</code></td></tr><tr><td><code>mcp.json</code></td><td><code>add_mcp_server</code></td><td>MCP servers attached to this agent only</td></tr><tr><td><code>mcp-auth/&lt;server&gt;.json</code></td><td>the OAuth flow</td><td>Stored tokens for one url server. Never leaves disk</td></tr><tr><td><code>skills/&lt;slug&gt;/SKILL.md</code></td><td><code>add_skill</code> / <code>import_skill</code></td><td>One skill: frontmatter + procedure</td></tr><tr><td><code>skills/&lt;slug&gt;/**</code></td><td><code>import_skill</code></td><td>A skill&#39;s own <code>references/</code>, <code>scripts/</code>, data files</td></tr><tr><td><code>workspace/</code></td><td>the agent</td><td>Working directory when frontmatter sets <code>cwd: workspace</code></td></tr><tr><td>anything else</td><td>you</td><td>Reference assets the agent reads at run time</td></tr></tbody></table><p>A real one, <code>agents/content-creator/</code>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>AGENT.md</span></span>
<span class="line"><span>mcp.json</span></span>
<span class="line"><span>mcp-auth/magnific.json</span></span>
<span class="line"><span>.claude-plugin/plugin.json</span></span>
<span class="line"><span>.codex-plugin/plugin.json</span></span>
<span class="line"><span>skills/content-creator-pro/SKILL.md</span></span>
<span class="line"><span>skills/content-creator-pro/_meta.json</span></span>
<span class="line"><span>skills/content-creator-pro/voice.md</span></span>
<span class="line"><span>skills/content-creator-pro/human_writing.md</span></span>
<span class="line"><span>skills/content-creator-pro/content_tracker.py</span></span>
<span class="line"><span>skills/magnific/SKILL.md</span></span>
<span class="line"><span>skills/magnific/references/image-generation.md</span></span>
<span class="line"><span>skills/magnific/references/video-generation.md</span></span></code></pre></div><h2 id="agent-md" tabindex="-1"><code>AGENT.md</code> <a class="header-anchor" href="#agent-md" aria-label="Permalink to &quot;\`AGENT.md\`&quot;">​</a></h2><p>The parser is deliberate and small, and it is not YAML. A frontmatter block must be the literal <code>---</code> fence at the very start of the file. Inside it, each line is split on its <strong>first</strong> colon; the key is trimmed, the value is the raw rest of the line. There is no nesting, no list syntax, and no type coercion — <code>tools</code> is a comma-separated string, and <code>lead</code> is the <em>text</em> <code>true</code> or <code>yes</code>. Everything below the closing fence is the persona prompt.</p><table tabindex="0"><thead><tr><th>Key</th><th>Type</th><th>Default</th><th>Effect</th></tr></thead><tbody><tr><td><code>description</code></td><td>string</td><td>first body line, <code>#</code> stripped</td><td>How PRIME routes to this agent; shown in <code>list_agents</code></td></tr><tr><td><code>department</code></td><td>string</td><td>title-cased directory name</td><td>Groups the agent with its team</td></tr><tr><td><code>lead</code></td><td><code>true</code> | <code>yes</code></td><td>absent = false</td><td>Gives the agent delegation tools over its department</td></tr><tr><td><code>cwd</code></td><td>path</td><td>the agent directory</td><td>Where the agent runs</td></tr><tr><td><code>permission</code></td><td><code>all</code> | <code>read-only</code> | <code>custom</code></td><td><code>all</code></td><td>What the agent may do</td></tr><tr><td><code>tools</code></td><td>comma-separated names</td><td>empty</td><td>Exact allow-list, only meaningful with <code>permission: custom</code></td></tr><tr><td><code>model</code></td><td>model id</td><td>inherit</td><td>Model override for this agent</td></tr><tr><td><code>profile</code></td><td>provider profile id</td><td>inherit</td><td>Provider profile this agent defaults to</td></tr><tr><td><code>effort</code></td><td>effort mode</td><td>inherit</td><td>Default effort mode</td></tr><tr><td><code>hidden</code> / <code>enabled</code></td><td><code>true</code>/<code>yes</code> / <code>false</code>/<code>no</code></td><td>absent</td><td><code>hidden: true</code> or <code>enabled: false</code> drops the agent from the roster fed to PRIME</td></tr></tbody></table><p><code>cwd</code> resolution: a leading <code>~</code> expands to the home directory, an absolute path is used as-is, and anything else resolves against the agent&#39;s own directory. <code>agents/email</code> uses <code>cwd: workspace</code>, so it runs in <code>agents/email/workspace/</code>. The directory is created on spawn if it does not exist.</p><p>A retired agent stays on disk when hidden — Settings still lists it and can restore or re-publish it — but it no longer occupies space in PRIME&#39;s prompt or dilutes routing.</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">---</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">description: Invoices, quotations, and client billing for First Click Technology Solutions.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">department: Finance</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">cwd: /Users/said/Company/Invoices</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">lead: true</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">---</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">You are Said&#39;s Finance agent…</span></span></code></pre></div><h3 id="how-permission-is-enforced" tabindex="-1">How permission is enforced <a class="header-anchor" href="#how-permission-is-enforced" aria-label="Permalink to &quot;How permission is enforced&quot;">​</a></h3><p>The permission is enforced by the <strong>tool set</strong>, not only by a callback. A model cannot call a tool it was never handed; the <code>canUseTool</code> gate is the second line of defence, and it matters because it also covers MCP tools, which <code>tools</code> does not govern.</p><table tabindex="0"><thead><tr><th><code>permission</code></th><th>Tool set handed to the runtime</th><th>Gate</th></tr></thead><tbody><tr><td><code>read-only</code></td><td>exactly <code>Read</code>, <code>Grep</code>, <code>Glob</code></td><td>read-only gate on the same three</td></tr><tr><td><code>custom</code></td><td>the <code>claude_code</code> preset</td><td>allow-list gate built from <code>tools</code></td></tr><tr><td><code>all</code></td><td>the <code>claude_code</code> preset</td><td>allow-all</td></tr></tbody></table><p><code>Grep</code> and <code>Glob</code> are named explicitly rather than assumed: native builds may route search through Bash, so a read-only agent without them would have no way to search at all.</p><h2 id="mcp-json" tabindex="-1"><code>mcp.json</code> <a class="header-anchor" href="#mcp-json" aria-label="Permalink to &quot;\`mcp.json\`&quot;">​</a></h2><p>Per-agent MCP servers live in <code>mcp.json</code> — the same shape as Claude&#39;s <code>.mcp.json</code>, but deliberately <em>not</em> named <code>.mcp.json</code>. The agent directory is already loaded as a local plugin, and the plugin loader would auto-connect a <code>.mcp.json</code> on its own. Saidi reads this file explicitly and hands the result to the runtime, so behaviour is identical across runtimes.</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;mcpServers&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;magnific&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;type&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;http&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;url&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://mcp.magnific.com&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Two entry shapes are recognised. An entry with a <code>url</code> (and <code>type</code> other than <code>stdio</code>) is a remote server; otherwise a <code>command</code> is required and the entry is stdio.</p><table tabindex="0"><thead><tr><th>Field</th><th>Shape</th><th>Notes</th></tr></thead><tbody><tr><td><code>type</code></td><td><code>http</code> | <code>sse</code> | <code>stdio</code></td><td>For url entries, anything but <code>sse</code> normalizes to <code>http</code></td></tr><tr><td><code>url</code></td><td>string</td><td>Required for http/sse</td></tr><tr><td><code>headers</code></td><td><code>{ string: string }</code></td><td>Static headers merged with any OAuth header</td></tr><tr><td><code>command</code></td><td>string</td><td>Required for stdio</td></tr><tr><td><code>args</code></td><td><code>string[]</code></td><td>Non-string members are dropped</td></tr><tr><td><code>env</code></td><td><code>{ string: string }</code></td><td>Passed on top of the default environment</td></tr></tbody></table><p>Server names are validated on write: 2–40 characters, <code>^[a-z0-9][a-z0-9_-]*$</code>, and <code>saidi</code>, <code>saidi_mem</code>, and <code>saidi_dev</code> are reserved for Saidi&#39;s own in-process servers. On read, an entry whose name fails validation or which normalizes to nothing is skipped — the file keeps it, the runtime does not see it. Attached servers are merged <em>before</em> Saidi&#39;s built-ins, so a built-in always wins a collision.</p><h2 id="oauth-for-remote-servers" tabindex="-1">OAuth for remote servers <a class="header-anchor" href="#oauth-for-remote-servers" aria-label="Permalink to &quot;OAuth for remote servers&quot;">​</a></h2><p>Only <code>http</code>/<code>sse</code> servers authenticate. The path is: probe → &quot;needs auth&quot; → authorize in the browser → tokens on disk → headers injected on every spawn.</p><p><strong>Probe.</strong> Saidi connects to one configured server exactly the way a runtime would — an <code>http</code> config tries streamable HTTP and falls back to legacy SSE, an <code>sse</code> config tries SSE only, a stdio config spawns the command — lists its tools, then disconnects. The timeout is 10 seconds and tool listing follows at most 20 pages of cursor. The result is either the tool list or the reason it failed. A failure is reported as <code>needsAuth</code> when the error is an <code>UnauthorizedError</code>, carries code <code>401</code>, or its message matches <code>401</code>, <code>unauthorized</code>, or <code>invalid_token</code>. Probes only supply an auth provider when tokens already exist, so a bare 401 reads as &quot;needs auth&quot; rather than triggering a refresh dance against an unknown server.</p><p><strong>Authorize.</strong> Starting auth registers a client with the server using this metadata:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;client_name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Saidi&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;redirect_uris&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;http://127.0.0.1:4317/api/mcp/oauth/callback&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;grant_types&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;authorization_code&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;refresh_token&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;response_types&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;code&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;token_endpoint_auth_method&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;none&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>The redirect URL is built from the configured host and port; a wildcard bind (<code>0.0.0.0</code> or <code>::</code>) is rewritten to <code>127.0.0.1</code> so the browser can actually reach it. If stored credentials are enough, the call returns <code>authorized: true</code> and nothing opens. Otherwise it returns the authorization URL for the UI to open, and the pending request — keyed by a random state id — is held for 10 minutes. The browser comes back to <code>/api/mcp/oauth/callback</code>, the code is exchanged, and the tokens are written.</p><p><strong>Storage.</strong> One file per agent + server, <code>agents/&lt;name&gt;/mcp-auth/&lt;server&gt;.json</code>:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;serverUrl&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://mcp.magnific.com&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;clientInformation&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;client_id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;…&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;redirect_uris&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;…&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">], </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;scope&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;…&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> },</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;tokens&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;access_token&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;…&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;refresh_token&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;…&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;token_type&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Bearer&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;expires_in&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">259200</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> },</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;obtainedAt&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1783266333672</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><strong>Use.</strong> Every spawn reads the agent&#39;s servers <em>with auth</em>: for each server that has stored tokens, a fresh <code>Authorization: Bearer …</code> header is merged over the configured headers. A token within 60 seconds of expiry is refreshed first. If the refresh throws, the stale token is kept deliberately — the server will 401 and the MCP tab will show &quot;needs auth&quot;, which is a better outcome than a hard failure inside the agent&#39;s next task.</p><p><code>mcp-auth/</code> is never packed into the agent&#39;s database document and is never pruned from disk. Those tokens exist in exactly one place.</p><h2 id="skills" tabindex="-1">Skills <a class="header-anchor" href="#skills" aria-label="Permalink to &quot;Skills&quot;">​</a></h2><p><strong>Discovery.</strong> A skill is <code>skills/&lt;slug&gt;/SKILL.md</code>. The listing walks the <code>skills/</code> directory, ignores any subdirectory without a <code>SKILL.md</code>, and reads <code>name</code> and <code>description</code> from the frontmatter (surrounding quotes are stripped, because real-world skills quote their values). A skill whose frontmatter fails to parse still lists, under its directory name.</p><p><strong>Loading.</strong> The agent directory itself is handed to the runtime as a local plugin, with setting sources switched off entirely. That is what keeps an agent&#39;s skills, subagents, hooks, and configuration isolated from Saidi&#39;s own and from the user&#39;s global Claude configuration — the agent gets its home directory and nothing else.</p><p><strong>Authoring.</strong> Writing a skill produces frontmatter with <code>name</code> and <code>description</code> (whitespace collapsed) followed by the body. The slug is validated the same way an agent name is, capped at 60 characters, and the resolved target must sit inside the agent&#39;s <code>skills/</code> directory.</p><p><strong>Importing.</strong> <code>import_skill</code> fetches from a URL and returns one of three results without touching disk:</p><table tabindex="0"><thead><tr><th>Result</th><th>When</th></tr></thead><tbody><tr><td><code>skill</code></td><td>A <code>SKILL.md</code> was found — files are returned ready for review, plus the list of scripts among them</td></tr><tr><td><code>page</code></td><td>Plain text or HTML with no frontmatter — PRIME can author a <code>SKILL.md</code> from it</td></tr><tr><td><code>error</code></td><td>Binary content, a failed fetch, or no <code>SKILL.md</code> at the given location</td></tr></tbody></table><p>A GitHub <code>/tree/</code> URL is walked recursively through <code>gh api</code> (already authenticated, so private repos work) with the public REST API as fallback. A <code>/blob/</code> URL, a raw URL, or any other page is fetched as a single file. The caps are boundaries, not suggestions:</p><table tabindex="0"><thead><tr><th>Cap</th><th>Value</th></tr></thead><tbody><tr><td>Files per skill</td><td>50</td></tr><tr><td>Bytes per file</td><td>256 KB</td></tr><tr><td>Bytes total</td><td>1 MB</td></tr><tr><td>Page text kept</td><td>20,000 characters</td></tr><tr><td>Fetch timeout</td><td>30 s</td></tr></tbody></table><p><code>SKILL.md</code> must sit at the root of the folder you point at, or the import errors rather than guessing. Binary files are skipped with a note. Files counted as scripts are those under <code>scripts/</code> or ending in <code>.sh</code>, <code>.py</code>, <code>.js</code>, <code>.ts</code>, <code>.rb</code>.</p><p>When the files are finally written, every relative path must resolve inside the skill directory — a single unsafe path refuses the entire import, because the remote repository chose those names.</p><p>Skills installed from the marketplace carry a <code>_meta.json</code> alongside <code>SKILL.md</code> recording owner, slug, version, and the upstream commit. See <a href="/docs/guides/marketplace">Marketplace</a>.</p><h2 id="the-report-contract" tabindex="-1">The report contract <a class="header-anchor" href="#the-report-contract" aria-label="Permalink to &quot;The report contract&quot;">​</a></h2><p>Every custom Claude agent and every project agent — in both <code>ask</code> and <code>work</code> mode — gets the report contract appended <strong>last</strong> in its system prompt, closest to the work. Its rules:</p><ul><li>Ten lines or fewer by default; never more than twenty-five.</li><li>Open with the verdict — <code>DONE</code>, <code>PARTIAL</code>, or <code>BLOCKED</code> — then one line per thing asked.</li><li>Every claim carries its proof inline and nothing else: a <code>file:line</code>, a command and its exit code, a commit hash, or a count.</li><li>Never paste file contents, diffs, logs, test output, or code blocks. Cite the path.</li><li>The one exception: when a criterion asks for something to be <em>in</em> the report — a table, a list of states, a set of findings — that content is the deliverable and goes inline in full. Writing it to a file and citing the path does not satisfy it.</li><li>No narration. Only what is true now and how it can be checked.</li><li>Say ✗ plainly for anything not done, with the reason on one line.</li></ul><p>The reasoning is economic: a final message is a handover into another model&#39;s context, and that context is replayed on every later turn. A long report is not paid for once. It is also self-defeating, because anything over the context budget is clipped before the reader sees it. The contract deliberately does not go to the verifier or the memory curator — both already have strict output formats of their own.</p><p>Three other fragments are appended to a custom agent&#39;s system prompt, in this order: the persona body, a workspace line naming the working directory, an execution-efficiency rule (batch independent read-only inspections, keep mutations sequential), an approval-integrity rule (never claim the user approved something unless the approval is quoted in the current task text), then the report contract.</p><h2 id="custom-agents-vs-project-agents" tabindex="-1">Custom agents vs project agents <a class="header-anchor" href="#custom-agents-vs-project-agents" aria-label="Permalink to &quot;Custom agents vs project agents&quot;">​</a></h2><p>Both use the same spawn machinery, and both get the report contract. Everything else differs.</p><table tabindex="0"><thead><tr><th></th><th>Custom agent</th><th>Project agent</th></tr></thead><tbody><tr><td>Defined by</td><td><code>agents/&lt;name&gt;/AGENT.md</code></td><td>An entry in the project registry</td></tr><tr><td>Rooted at</td><td><code>cwd</code> frontmatter, default the agent dir</td><td>The repository checkout</td></tr><tr><td>Configuration</td><td>The agent dir loaded as a local plugin; setting sources off</td><td>The repo&#39;s own <code>.claude/</code> (<code>project</code> + <code>local</code> setting sources)</td></tr><tr><td>Modes</td><td>One mode; behaviour comes from the persona</td><td><code>ask</code> (read-only Q&amp;A) and <code>work</code> (make a change)</td></tr><tr><td>Permission</td><td><code>all</code> / <code>read-only</code> / <code>custom</code> from frontmatter</td><td><code>ask</code> is <code>Read</code>/<code>Grep</code>/<code>Glob</code> only; <code>work</code> gets the full preset</td></tr><tr><td>Git</td><td>None</td><td>Cuts a <code>saidi/*</code> branch, commits, pushes, opens a PR — or commits on the current branch</td></tr><tr><td>MCP</td><td>The agent&#39;s own <code>mcp.json</code>, plus <code>saidi_mem</code></td><td><code>saidi_mem</code> and whatever the repo configures</td></tr><tr><td>Memory</td><td><code>memory/agents/&lt;name&gt;.md</code></td><td><code>memory/projects/&lt;name&gt;.md</code></td></tr><tr><td>Delegated by</td><td><code>run_agent</code></td><td><code>delegate_to_project</code></td></tr><tr><td>Policy</td><td>Frontmatter</td><td><a href="/docs/reference/project-policy">Project policy</a></td></tr></tbody></table><p>Both inject their long-term memory block into the <strong>task text</strong>, not the system prompt — a <code>remember</code> save mid-run would otherwise change the system prompt and invalidate the resumed session&#39;s entire prompt cache. It is sent on a fresh session only, and re-sent after a context compaction.</p><p>Only <code>forge</code> is scaffolded automatically on a fresh install. Every other agent is something you or PRIME created.</p><h2 id="storage" tabindex="-1">Storage <a class="header-anchor" href="#storage" aria-label="Permalink to &quot;Storage&quot;">​</a></h2><p>The database is the source of truth for agent definitions; the directory tree is a materialized working copy that the runtimes load. Every mutation writes the agent&#39;s whole directory through to its document, best-effort — a failed persist never breaks the mutation — the materialized directory stays authoritative for the running agent.</p><p>Packing is bounded by construction. Files are taken <strong>smallest first</strong> against a 12 MB budget, so the definition itself — <code>AGENT.md</code>, <code>plugin.json</code>, <code>skills/*/SKILL.md</code>, <code>mcp.json</code>, all kilobytes — always fits, and only a fat tail of large files is reported as skipped and left on disk. Never packed at all: <code>mcp-auth/</code> (secrets), <code>workspace/</code> (run output), and <code>node_modules</code> at any depth. Anything excluded from the document is also preserved on disk by the pruner, because for those paths the disk is the only copy.</p><h2 id="the-shipped-roster" tabindex="-1">The shipped roster <a class="header-anchor" href="#the-shipped-roster" aria-label="Permalink to &quot;The shipped roster&quot;">​</a></h2><p>The agents in this install, their departments, and what each owns:</p><table tabindex="0"><thead><tr><th>Agent</th><th>Department</th><th>Owns</th></tr></thead><tbody><tr><td><code>company</code></td><td>Company (lead)</td><td>Company knowledge and operations — clients, contracts, proposals, HR, legal, project records. Runs from the company folder</td></tr><tr><td><code>content-creator</code></td><td>Creative (lead)</td><td>Graphical content: social posts, banners, logos, mockups, slides, image edits. Attaches the <code>magnific</code> MCP server</td></tr><tr><td><code>corex-crm</code></td><td>Communication</td><td>The Apex Aion CRM — reading records, creating and updating entries, pulling data. Attaches the <code>corex-prod</code> MCP server</td></tr><tr><td><code>email</code></td><td>Communication (lead)</td><td>Email search, drafting, sending, and inbox triage. Runs from its own <code>workspace/</code>; carries the <code>himalaya</code> skill</td></tr><tr><td><code>finance</code></td><td>Finance (lead)</td><td>Invoices, quotations, and client billing. Runs inside the real Invoices folder and matches its house format</td></tr><tr><td><code>forge</code></td><td>Development (lead)</td><td>Engineering lead: routes coding work to repo agents, and handles desktop/environment tasks itself (VPN, app runs, browser, screenshots)</td></tr><tr><td><code>tasks</code></td><td>Personal (lead)</td><td>Personal task and thought organizer — captures brain-dumps, keeps a persistent list, reports what is on the plate</td></tr></tbody></table><p>Departments and leads are covered in <a href="/docs/concepts/agents-and-departments">Agents &amp; Departments</a>.</p>`,66)])])}const u=t(i,[["render",d]]);export{g as __pageData,u as default};
